      { "n": 4, "page": 2, "action": "8 s. Her father leans on the railing and calls down.", "sound": ["music"], "lines": ["f03"] },
      { "n": 5, "page": 2, "action": "8 s. Nina sits back on her heels, yellow fingers, and admires her sun.", "sound": ["a satisfied little chord"], "lines": ["f04"] },
      { "n": 6, "page": 3, "action": "4 s. Scene 2, swish. A rattle of small wheels, coming closer. Nina looks up. No words.", "sound": ["scooter wheels rolling closer"], "lines": [] },
      { "n": 7, "page": 3, "action": "5 s. Rami whizzes round the corner, helmet on, grinning, looking down the street, and rides straight across the sun. The wheel leaves a grey stripe. Not loud: a quick swish.", "sound": ["a quick swish of wheels"], "lines": ["f05"] },
      { "n": 8, "page": 3, "action": "8 s. Slow push in on the stripe through the middle of the sun. The music stops. Hold.", "sound": ["silence, then one low note"], "lines": [] },
      { "n": 9, "page": 4, "action": "10 s. Close on Nina. Warm orange and red rise behind her like heat over a road, and her cheeks go red.", "sound": ["a low, warm hum rising slowly"], "lines": ["f06"] },
      { "n": 10, "page": 4, "action": "9 s. Her hands close into fists. Her shoulders lift. The red glow is at its strongest. No sudden loud sound.", "sound": ["the hum holds"], "lines": ["f07"] },
      { "n": 11, "page": 4, "action": "8 s. Nina glances at Rami's scooter. Her fists tighten. Hold the moment of choice. No words.", "sound": ["a heartbeat-like soft drum, slow"], "lines": [] },
      { "n": 12, "page": 5, "action": "9 s. Nina stamps her foot, opens her hands, points at the stripe and shouts. Her voice is loud but clear; the red glow pulses once and starts to fade.", "sound": ["one foot stamp", "the hum breaks off"], "lines": ["f08"] },
      { "n": 13, "page": 5, "action": "5 s. On the balcony, her father straightens and watches, ready, but stays where he is. No words.", "sound": ["quiet"], "lines": [] },
      { "n": 14, "page": 6, "action": "8 s. Rami looks down at the sun and the stripe. His cheeks go pink.", "sound": ["a soft, sorry note"], "lines": ["f09"] },
      { "n": 15, "page": 6, "action": "5 s. He looks up at Nina.", "sound": ["quiet"], "lines": ["f10"] },
      { "n": 16, "page": 7, "action": "12 s. Scene 3, the sunbeam. Nina looks at the stripe for a long time. The red behind her fades to soft yellow. Her fists open slowly. Breathing moment: no words for 5 s.", "sound": ["one long, slow breath", "the music returns, very soft"], "lines": ["f11"] },
      { "n": 17, "page": 7, "action": "9 s. From above: the camera turns so that the stripe points out from the sun like a ray. Nina tilts her head.", "sound": ["a light chime"], "lines": ["f12"] },
      { "n": 18, "page": 8, "action": "9 s. Rami lays his scooter down carefully, crouches by the chalk box and holds up a yellow stick.", "sound": ["the scooter laid down", "chalk sticks clinking in the box"], "lines": ["f13"] },
      { "n": 19, "page": 8, "action": "8 s. Nina nods and hands him a second yellow stick.", "sound": ["music, warmer"], "lines": ["f14"] },
      { "n": 20, "page": 9, "action": "16 s. Scene 4, beams. Fast motion from above: beams spring out all round the sun, long and short, straight and wiggly, in yellow and orange.", "sound": ["chalk scratching in rhythm", "bouncy music"], "lines": ["f15", "f16"] },
      { "n": 21, "page": 10, "action": "10 s. Close: Rami draws two eyes; Nina draws a smile, then sunglasses. Both burst out laughing.", "sound": ["chalk", "giggles"], "lines": ["f17"] },
      { "n": 22, "page": 11, "action": "12 s. The camera rises slowly to show the whole sun, from the bench to the lamp post, with the grey stripe as its longest beam. No words: let the picture land.", "sound": ["music swelling gently"], "lines": [] },
      { "n": 23, "page": 11, "action": "8 s. Nina and Rami stand back, hands on hips, looking at it.", "sound": ["birds"], "lines": [] },
      { "n": 24, "page": 12, "action": "9 s. Scene 5, the biggest sun. Her father leans over the balcony and calls down, laughing.", "sound": ["music"], "lines": ["f18"] },
      { "n": 25, "page": 12, "action": "6 s. Nina and Rami look up and laugh.", "sound": ["laughter"], "lines": [] },
      { "n": 26, "page": 13, "action": "10 s. They sit on the doorstep in the shade, side by side, chalky, the scooter next to them.", "sound": ["birds", "warm music"], "lines": ["f19"] },
      { "n": 27, "page": 13, "action": "8 s. Nina leans her shoulder against Rami's.", "sound": ["warm music"], "lines": ["f20"] },
      { "n": 28, "page": 13, "action": "14 s. Closing image from above: the giant chalk sun on the pavement with its sunglasses and its long grey beam, the two children small on the doorstep. Hold the still picture 6 s while the music ends, then stop. No autoplay.", "sound": ["the last notes of the music", "birds"], "lines": [] }
