      { "n": 1, "picture": "A grown-up drips a few drops of oil onto a child's open palms and sprinkles a pinch of brown cocoa powder over them; the child's hands look smeared and brown.", "loop": false },
      { "n": 2, "picture": "The child holds the hands under a running tap at a sink, with no soap; afterwards the hands still show brown smears, and the child looks puzzled.", "loop": false },
      { "n": 3, "picture": "The child rubs soap into a white lather, singing (small music notes, no letters), palm on palm and back on back; then holds up clean hands, smiling.", "loop": false }
