      { "n": 1, "page": 1, "action": "12 s. Scene 1, the market. Wide on the late-afternoon autumn market, golden light, long shadows. The camera drifts slowly along the stalls; far up, a flock of birds (one silhouette, repeated) flies south. No words: let the place breathe. Keep the lower fifth calm for captions in every shot.", "sound": ["a light hand drum and plucked strings, cheerful", "market murmur, thinning out", "a crate set down"], "lines": [] },
      { "n": 2, "page": 1, "action": "8 s. The camera arrives at the pomegranate stall. The seller is mid-laugh with a passer-by; her laugh is the first sound we hear clearly.", "sound": ["a big rolling laugh: ha-HA-ha"], "lines": ["f01"] },
      { "n": 3, "page": 1, "action": "7 s. Sofia and Liam behind the table in aprons too big for them; Liam rolls up his sleeves, Sofia ties her apron strings twice round.", "sound": ["the cheerful tune"], "lines": ["f02"] },
      { "n": 4, "page": 1, "action": "6 s. Close on the seller laughing; her whole body shakes, her headscarf bobs. A sound joke, no words.", "sound": ["her laugh"], "lines": [] },
      { "n": 5, "page": 2, "action": "6 s. Close on the ten pomegranates in a row, glowing in the low sun. A sparrow hops onto the table edge, looks, and hops away. Breathing room.", "sound": ["a sparrow chirp", "soft wind"], "lines": [] },
      { "n": 6, "page": 2, "action": "9 s. Liam taps each pomegranate once: ten taps, each with a soft wooden tok and a plucked note climbing one step higher. He speaks after the tenth note.", "sound": ["ten taps with ten rising notes"], "lines": ["f03"] },
      { "n": 7, "page": 2, "action": "7 s. Sofia carries two empty baskets from behind the crates and sets them on the table, one, two.", "sound": ["basket thump", "basket thump"], "lines": [] },
      { "n": 8, "page": 3, "action": "10 s. Scene 2, the job. The seller, hands on hips, gives them the job; she nods at the baskets.", "sound": ["the tune, softer"], "lines": ["f04", "f05"] },
      { "n": 9, "page": 3, "action": "6 s. She walks off to stack crates; her laugh rolls away down the row and echoes. Liam answers before she is gone.", "sound": ["crates stacking", "her laugh fading down the row"], "lines": ["f06"] },
      { "n": 10, "page": 4, "action": "9 s. Liam lines up the two baskets with great care, like a judge.", "sound": ["baskets scraped into place"], "lines": ["f07"] },
      { "n": 11, "page": 4, "action": "11 s. Counting in: the pomegranates hop into the left basket one at a time on five beats, then into the right basket on five beats, each with a plucked note (two matching rising phrases). The line is spoken on the beats.", "sound": ["five plucked notes", "five plucked notes, the same tune again"], "lines": ["f08"] },
      { "n": 12, "page": 4, "action": "6 s. Two equal baskets side by side. Liam folds his arms and lifts his chin. Hold 2 s after the line.", "sound": ["a satisfied little chord"], "lines": ["f09"] },
      { "n": 13, "page": 5, "action": "7 s. Scene 3, the baker. Down the row comes the baker at a fast trot, a puff of flour off his apron with every step. Comic, no words.", "sound": ["hurried footsteps", "a soft poof of flour on each step", "the music speeds up"], "lines": [] },
      { "n": 14, "page": 5, "action": "7 s. He skids to a stop at the table, holds up seven fingers and puffs out his request.", "sound": ["a skid", "puffing breath"], "lines": ["f10"] },
      { "n": 15, "page": 5, "action": "7 s. Liam looks from the baker to his two perfect baskets, crestfallen.", "sound": ["a falling two-note sigh on strings"], "lines": ["f11"] },
      { "n": 16, "page": 6, "action": "8 s. Sofia taps her chin, thinking; then she lifts one pomegranate from the right basket and it arcs across to the left, then a second one. Each hop has its own plucked note.", "sound": ["a thinking tick-tock on wood block", "two hops, two notes"], "lines": ["f12"] },
      { "n": 17, "page": 6, "action": "8 s. Sofia presents the baskets to the baker with both hands.", "sound": ["a bright chord"], "lines": ["f13"] },
      { "n": 18, "page": 6, "action": "10 s. Liam counts both baskets slowly, finger hovering over each fruit; the camera stays close on him. Hold 2 s on his surprised face after the line.", "sound": ["soft ticks as he counts"], "lines": ["f14"] },
      { "n": 19, "page": 7, "action": "8 s. Scene 4, the doctor. The doctor walks up calmly, holding her very small bag in both hands, and asks politely.", "sound": ["calm footsteps", "the tune slows down"], "lines": ["f15"] },
      { "n": 20, "page": 7, "action": "5 s. She lifts the tiny bag a little to show it. A small visual joke.", "sound": ["a tiny clasp click"], "lines": ["f16"] },
      { "n": 21, "page": 7, "action": "7 s. Sofia lifts one pomegranate out of the doctor's basket and sets it on the bare table. The camera stays on the baskets; at the edge of the frame Liam's hand picks the loose pomegranate up without his noticing. Sharp viewers will see it. No words.", "sound": ["a soft wooden tok on the table"], "lines": [] },
      { "n": 22, "page": 8, "action": "9 s. Liam counts the baskets aloud, slowly; his other hand, holding the pomegranate, hangs at his side.", "sound": ["soft counting ticks"], "lines": ["f17"] },
      { "n": 23, "page": 8, "action": "8 s. The music stops with a comic sting (never scary). Liam's face falls; he looks at everyone.", "sound": ["a comic plucked 'boing'", "silence"], "lines": ["f18"] },
      { "n": 24, "page": 9, "action": "6 s. Scene 5, the search. Quick cuts begin: Sofia puts her head into an empty crate.", "sound": ["tiptoe pizzicato music", "a hollow crate echo"], "lines": ["f19"] },
      { "n": 25, "page": 9, "action": "5 s. The baker looks behind the sacks; a cloud of flour puffs up round his head.", "sound": ["a poof of flour", "a sneeze, small"], "lines": [] },
      { "n": 26, "page": 9, "action": "5 s. The doctor opens her tiny bag and peers into it with great seriousness.", "sound": ["clasp click"], "lines": ["f20"] },
      { "n": 27, "page": 9, "action": "6 s. The seller turns out her apron pocket: a pencil, a handkerchief, a lemon, but no pomegranate.", "sound": ["little objects plopping onto the table"], "lines": ["f21"] },
      { "n": 28, "page": 9, "action": "8 s. Wide: everyone bent over, searching. Liam in the middle scratches his head with his free hand; in the other hand, clearly visible, is the pomegranate. Let the viewer spot it first. No words.", "sound": ["the tiptoe music, with a wink of a note"], "lines": [] },
      { "n": 29, "page": 10, "action": "7 s. Scene 6, found. Sofia straightens up, sees Liam's hand, and starts to giggle.", "sound": ["a giggle trying not to come out"], "lines": ["f22"] },
      { "n": 30, "page": 10, "action": "6 s. Close on Liam's hand and the pomegranate in it. He stares at it. One bright 'ding'. No words.", "sound": ["a single bell-like ding"], "lines": [] },
      { "n": 31, "page": 10, "action": "9 s. Everyone bursts out laughing, the seller loudest; Liam laughs at himself too.", "sound": ["laughter building", "the seller's big laugh on top"], "lines": ["f23"] },
      { "n": 32, "page": 11, "action": "9 s. Liam works it out aloud, pointing to the baker's basket, the doctor's basket and his own hand in turn.", "sound": ["three soft ticks, one per point"], "lines": ["f24"] },
      { "n": 33, "page": 11, "action": "8 s. The baker grins and holds out his basket; the found pomegranate hops in with a plucked note. Sofia sums it up.", "sound": ["one hop, one note", "a happy chord"], "lines": ["f25", "f26"] },
      { "n": 34, "page": 11, "action": "6 s. Sofia and Liam high-five across the baskets. No words.", "sound": ["a high-five slap", "the tune returns"], "lines": [] },
      { "n": 35, "page": 12, "action": "8 s. Scene 7, always ten. Sofia pushes the two baskets side by side; a steady musical beat starts. She speaks on the beat.", "sound": ["a steady hand-drum beat begins"], "lines": ["f27"] },
      { "n": 36, "page": 12, "action": "7 s. Close on Sofia, delighted by her discovery.", "sound": ["the beat"], "lines": ["f28"] },
      { "n": 37, "page": 12, "action": "6 s. Liam's eyes light up.", "sound": ["the beat", "a rising whistle note"], "lines": ["f29"] },
      { "n": 38, "page": 12, "action": "14 s. The juggle, Liam's daydream: the background melts into warm plain colour and the two baskets stand alone. On each beat one pomegranate hops from one basket to the other, so the piles change size, while a row of ten small round slots under the baskets always stays exactly full (dots, never digits). The narrator names a pair on the beats; let two or three hops pass with no words between lines. At the end the colour snaps back to the market.", "sound": ["the beat", "one plucked note per hop", "a soft chime on 'always ten'"], "lines": ["f30", "f31", "f32"] },
      { "n": 39, "page": 12, "action": "6 s. Back at the stall: Liam has really moved one pomegranate into the baker's basket, leaving the doctor only one. The doctor laughs and holds up a hand.", "sound": ["the beat stops", "the doctor's laugh"], "lines": ["f33"] },
      { "n": 40, "page": 12, "action": "5 s. Liam quickly hops it back. Grin.", "sound": ["one hop back, one note"], "lines": ["f34"] },
      { "n": 41, "page": 13, "action": "9 s. Scene 8, goodbyes. The baker pays (coins clink into the seller's tin), grabs his basket and hurries off in a trail of flour puffs.", "sound": ["coins clinking", "hurried footsteps fading"], "lines": ["f35"] },
      { "n": 42, "page": 13, "action": "9 s. The doctor pays, smiles and walks away the other way, turning once to wave.", "sound": ["coins", "calm footsteps"], "lines": ["f36"] },
      { "n": 43, "page": 13, "action": "8 s. The empty table and two empty baskets; Sofia and Liam look at each other, tired and happy. The light turns redder. A breath, no words.", "sound": ["evening birds", "the tune, very soft"], "lines": [] },
      { "n": 44, "page": 14, "action": "8 s. The seller comes back wiping her hands on her apron, beaming.", "sound": ["her footsteps", "a warm chord"], "lines": ["f37"] },
      { "n": 45, "page": 14, "action": "10 s. She bends and lifts a cloth bundle from under the table and opens it: one more pomegranate, its skin split. She speaks low, like a secret, then warm.", "sound": ["cloth rustle"], "lines": ["f38", "f39"] },
      { "n": 46, "page": 15, "action": "12 s. Close: her thumbs break the fruit open with a soft crack. The seeds catch the low sun and glow like tiny red lanterns; a few small sparkles. Music swells gently. Hold 4 s on the seeds with no words.", "sound": ["a soft crack", "a shimmer of chimes", "the tune swells, gently"], "lines": [] },
      { "n": 47, "page": 15, "action": "7 s. Liam leans in close, amazed.", "sound": ["the shimmer fades"], "lines": ["f40"] },
      { "n": 48, "page": 15, "action": "9 s. The seller laughs her biggest laugh of the whole film.", "sound": ["her biggest laugh"], "lines": ["f41"] },
      { "n": 49, "page": 15, "action": "11 s. The three of them eat the seeds, one at a time, in the last golden light. The narrator's line comes in the middle of the shot.", "sound": ["the tune, slow and warm"], "lines": ["f42"] },
      { "n": 50, "page": 15, "action": "14 s. Closing image: the stall at sunset, two empty baskets side by side and the open pomegranate on its cloth. Nothing moves except the light slowly fading. Hold the still picture 6 s while the music ends, then stop. No autoplay.", "sound": ["the last notes of the tune", "evening birds"], "lines": [] }
