  "cast": ["c11-felix", "c11-grandpa", "c11-friend"],
  "pages": [
    {
      "n": 1,
      "art": "A sunny city square in spring: pale stone paving, a round fountain in the middle, a bakery with a striped awning, flower boxes with red geraniums, and on one side a tall stone clock tower with a big round white clock face carrying twelve black marks and two black hands (no numerals, no words; the hands show twenty to five, a time the text does not name). Felix, in the foreground, runs in with his shoelace undone, too late: the football game is over and two children are walking away with the ball. Felix looks up at the clock, puzzled. Feeling: comic frustration. Calm area: the blue sky across the top, beside the tower.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 2,
      "art": "The arched wooden door at the foot of the clock tower stands open. Grandpa, the clock keeper, in a waistcoat and flat cap, with a ring of big keys on his belt, holds out his hand to Felix. Felix looks up at the tower, eyes wide. Feeling: an invitation, a secret place opening. Calm area: the stone wall of the tower above the door, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 3,
      "art": "A narrow spiral stone staircase seen from below, winding up; small slit windows let in stripes of sky. Grandpa climbs steadily ahead with one hand on the rope rail; Felix follows, a step behind, counting on his fingers. Feeling: adventure, a long climb. Calm area: the plain curved wall at the top of the picture.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 4,
      "art": "The clock room at the top: a small room with a wooden floor. In the middle, three or four big brass gear wheels on a simple frame, their teeth meshing, one turning the next (simple shapes, no fine detail). One whole wall is the back of the giant clock face: round, pale, lit from outside by the sun, the twelve marks glowing through it as dark shadows. Felix stands still, mouth open; Grandpa smiles beside him. Feeling: wonder, like standing inside a heart. Calm area: the dim upper part of the room, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 5,
      "art": "Grandpa winding the clock with a big iron crank handle fitted into the frame, leaning into it, cheeks pink. On a small workbench nearby lies an old wooden practice clock face with twelve marks and two movable hands, one short and one long. Felix is already reaching for it. Feeling: work, then a lesson about to start. Calm area: the upper wall, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 6,
      "art": "Close: Grandpa and Felix bent over the wooden practice clock on the workbench. The long hand points straight up; the short hand points at the third mark after the top (three o'clock). Grandpa's finger rests on the short hand; Felix's finger traces the marks. Feeling: careful learning. Calm area: the plain workbench wood across the bottom.",
      "zone": { "side": "full", "v": "bottom", "size": "m" },
      "image": null
    },
    {
      "n": 7,
      "art": "The same practice clock, now with the long hand pointing straight down and the short hand halfway between the third and fourth marks (half past three). A curved dotted arrow shows the long hand's half-turn from top to bottom. Felix, eyes closed, sways a little as if singing to himself; Grandpa nods. Feeling: it clicks. Calm area: the plain upper wall of the clock room, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 8,
      "art": "Three small scenes of Felix practising, in one picture like a strip: at the breakfast table pointing at a round kitchen clock; at his bedroom window looking at the tower clock far away; at Grandpa's kitchen table, pointing at a clock showing ten o'clock (long hand up, short hand at the tenth mark), mouth open in a shout, while Grandpa raises one eyebrow. Feeling: effort, a funny mistake, practice. Calm area: a plain band of wall across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 9,
      "art": "The square in the late morning: Felix's friend, a girl with short curly hair and a yellow jacket, runs up to Felix with one hand hiding something behind her back, the other hand pointing at the fountain. Felix stands by the fountain's stone edge, swallowing. The tower clock in the background shows a little after eleven. Feeling: a promise, a little nerves. Calm area: the sky across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 10,
      "art": "In front of the bakery, Felix kneels on the paving with a few glass marbles in a chalk circle. He has just looked up: the tower clock in the background clearly shows half past three (long hand straight down, short hand halfway between the third and fourth marks). His hand is frozen mid-flick. Feeling: remembering just in time. Calm area: the sky across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 11,
      "art": "Felix walking across the square towards the fountain, hands in his pockets, marbles bulging in one pocket. Pigeons strut out of his way. The fountain splashes in flat layered arcs of water. The clock shows a little after half past three. Feeling: calm, purposeful. Calm area: the sky across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 12,
      "art": "Felix sitting on the stone edge of the fountain, chin in his hands, staring up at the tower clock: the long hand is nearly straight up, just before four. Two pigeons sit beside him. Feeling: waiting, a little suspense. Calm area: the sky beside the tower, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 13,
      "art": "Four o'clock exactly on the tower clock (long hand straight up, short hand at the fourth mark). Sound shown only as a few big curved lines rippling out from the tower, no letters. A burst of pigeons flies up from the square. Round the corner of the bakery, the friend comes running, cheeks red, waving. Felix stands up on the fountain edge, grinning. Feeling: triumph, joy. Calm area: the sky across the top, above the pigeons.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 14,
      "art": "Last picture of the book: the friend holds up a red and yellow paper windmill on a stick that spins in the breeze; Felix laughs. High up, in the small window under the tower clock (still showing just after four), Grandpa leans out and waves; Felix waves back. Warm afternoon light over the whole square. Feeling: pride, friendship, time on his side. Calm area: the stone paving across the bottom.",
      "zone": { "side": "full", "v": "bottom", "size": "m" },
      "image": null
    }
  ],
