      { "n": 1, "page": 1, "action": "12 s. Scene 1, the storm night. The village at night: trees bending in the wind as sweeping shapes, shadows of branches swaying across the house fronts, a shutter banging. The power of the storm is carried by sound and moving shadows; nothing breaks on screen. No words. Keep the lower fifth calm for captions in every shot.", "sound": ["a howling wind, deep and long", "a shutter banging", "rain gusts"], "lines": [] },
      { "n": 2, "page": 1, "action": "11 s. Inside: Diana in bed, blanket up to her nose, the night light glowing; branch shadows sway over her wall.", "sound": ["the wind, muffled", "a soft low drone"], "lines": ["f01"] },
      { "n": 3, "page": 1, "action": "8 s. The wind slowly dies down. The shadows stop moving. Diana's eyes close. A breath, no words.", "sound": ["the wind fading to nothing"], "lines": [] },
      { "n": 4, "page": 2, "action": "10 s. Scene 2, the morning. Still and clean: drops falling from the gutter, puddles shining, branches scattered over the street.", "sound": ["drips", "a single bird", "a calm piano tune"], "lines": ["f02"] },
      { "n": 5, "page": 2, "action": "8 s. Diana opens her window and leans out into the cold, clean air, looking down the street. No words.", "sound": ["a window opening", "a cold breeze"], "lines": [] },
      { "n": 6, "page": 2, "action": "10 s. The camera travels slowly down the street to the kindergarten and stops on the huge pine branch lying across its green gate.", "sound": ["the piano tune, a low note"], "lines": ["f03"] },
      { "n": 7, "page": 3, "action": "11 s. The little ones in raincoats wait in a line. The teacher grips the branch and pulls with all her might; it does not move.", "sound": ["a strained grunt", "a creak of wood"], "lines": ["f04"] },
      { "n": 8, "page": 3, "action": "7 s. Close on one little one's face crumpling into tears. Gentle, never frightening. No words.", "sound": ["a small sniffle"], "lines": [] },
      { "n": 9, "page": 4, "action": "10 s. Diana at her window sees it all; she pulls on her boots on the stairs and runs out down the street.", "sound": ["boots on stairs", "a door opening", "splashy running steps"], "lines": ["f05"] },
      { "n": 10, "page": 4, "action": "10 s. Diana pushes the branch with her hands, then her shoulder, feet slipping on the wet road. Nothing moves.", "sound": ["puffing", "boots skidding"], "lines": ["f06"] },
      { "n": 11, "page": 4, "action": "7 s. Diana stops, panting, and looks at her red hands; the little ones look at her hopefully. No words.", "sound": ["panting", "a small hopeful note"], "lines": [] },
      { "n": 12, "page": 4, "action": "9 s. The teacher shakes her head kindly.", "sound": ["the piano, a soft chord"], "lines": ["f07"] },
      { "n": 13, "page": 5, "action": "10 s. Diana stands still, thinking; then her face lights up.", "sound": ["a rising two-note idea"], "lines": ["f08"] },
      { "n": 14, "page": 5, "action": "11 s. Scene 3, the team. Diana knocks at the blue door. It opens: the twins, identical, sleepy, in matching yellow boots.", "sound": ["three knocks", "a door creak", "two identical yawns"], "lines": ["f09", "f10"] },
      { "n": 15, "page": 6, "action": "10 s. At the back of the bakery, a boy steps out still holding his broom.", "sound": ["a door bell", "a cheerful whistle"], "lines": ["f11"] },
      { "n": 16, "page": 6, "action": "11 s. From the corner house, the girl in the wheelchair rolls down her ramp, zipping up her coat.", "sound": ["wheels on a ramp", "a zip"], "lines": ["f12"] },
      { "n": 17, "page": 6, "action": "8 s. The five children walk and roll down the street together, a little procession. No words.", "sound": ["footsteps and wheels", "the tune, picking up a beat"], "lines": [] },
      { "n": 18, "page": 7, "action": "10 s. Diana's mother stands in the street and looks up at the wires between the poles, one by one, then at the branch, well away from them.", "sound": ["a careful, quiet tune"], "lines": ["f13"] },
      { "n": 19, "page": 7, "action": "8 s. Diana's mother checks that the branch lies well away from the poles, then rolls up her sleeves and steps to the thick end of the branch. No words.", "sound": ["a reassuring chord"], "lines": [] },
      { "n": 20, "page": 8, "action": "10 s. Scene 4, the muddle. Diana's mother and the five children take hold of the branch.", "sound": ["hands on wood"], "lines": ["f14"] },
      { "n": 21, "page": 8, "action": "10 s. Everyone pulls a different way: Diana's mother waits at the thick end, the twins pull one way, the bakery boy the other, Diana tugging a twig. The branch rocks and creaks and stays. Comic.", "sound": ["tug-of-war grunts", "a creaking rock", "a comic trombone slide"], "lines": ["f15"] },
      { "n": 22, "page": 9, "action": "9 s. The girl in the wheelchair rolls forward and raises her hand.", "sound": ["the music stops"], "lines": ["f16"] },
      { "n": 23, "page": 9, "action": "10 s. She points to places along the branch like a conductor; everyone takes their place and bends their knees.", "sound": ["one note per place, rising"], "lines": ["f17"] },
      { "n": 24, "page": 10, "action": "6 s. Silence. Behind the fence the little ones hold their breath, hands on their cheeks. No words.", "sound": ["silence", "a single drip"], "lines": [] },
      { "n": 25, "page": 10, "action": "11 s. The call, and the lift in one rhythm: Diana's mother and four children rise together and the branch comes up off the ground.", "sound": ["three drum beats and a big chord on 'lift'"], "lines": ["f18"] },
      { "n": 26, "page": 10, "action": "9 s. Close on the branch moving sideways, needles trembling.", "sound": ["the scrape of a branch lifting"], "lines": ["f19"] },
      { "n": 27, "page": 11, "action": "11 s. Again, in rhythm: step, step, step, they carry the branch to the grass at the side of the road and lay it down.", "sound": ["three drum beats and a chord", "heavy steps in rhythm"], "lines": ["f20"] },
      { "n": 28, "page": 11, "action": "8 s. The little ones cheer so loudly that a cat jumps off a wall. No words.", "sound": ["cheering", "a startled cat's mew"], "lines": [] },
      { "n": 29, "page": 12, "action": "11 s. Scene 5, the jobs. Quick cheerful cuts: the twins stack small branches, the bakery boy sweeps the path, the girl in the wheelchair gathers pine cones on her lap.", "sound": ["sweeping", "twigs clicking", "the tune, bright"], "lines": ["f21"] },
      { "n": 30, "page": 12, "action": "7 s. Diana puts both hands on the green gate. Hold. No words.", "sound": ["a held note"], "lines": [] },
      { "n": 31, "page": 13, "action": "9 s. The gate swings wide open. The little ones march in, one by one, waving.", "sound": ["the gate creaking open", "little marching feet", "the tune full and happy"], "lines": [] },
      { "n": 32, "page": 13, "action": "11 s. The teacher shakes every helper's hand, even the twins' muddy ones.", "sound": ["handshakes", "laughter"], "lines": ["f22"] },
      { "n": 33, "page": 13, "action": "8 s. The girl in the wheelchair gives a pine cone to the last little one, who holds it up like treasure. No words.", "sound": ["a tiny delighted squeal"], "lines": [] },
      { "n": 34, "page": 14, "action": "11 s. Scene 6, the next morning. Bright and still. Diana walks to the kindergarten with her school bag.", "sound": ["morning birds", "a calm version of the tune"], "lines": ["f23"] },
      { "n": 35, "page": 14, "action": "8 s. Close on the drawing of the twins: two identical boys in two identical drawings, side by side. A small visual joke. No words.", "sound": ["a playful two-note echo"], "lines": [] },
      { "n": 36, "page": 14, "action": "11 s. The camera moves slowly along the gate, past each crayon drawing in turn: the broom, the wheelchair, the two identical yellow-boot boys, the red coat.", "sound": ["one soft chime per drawing"], "lines": ["f24"] },
      { "n": 37, "page": 14, "action": "8 s. Diana stops at the red coat drawing and smiles. No words.", "sound": ["a warm chord"], "lines": [] },
      { "n": 38, "page": 14, "action": "14 s. Closing image: the kindergarten gate with five drawings, the cleared street behind, the old pine tree standing. Nothing moves but the drawings stirring a little in the breeze. Hold the still picture 6 s while the music ends, then stop. No autoplay.", "sound": ["the last notes of the piano", "a gentle breeze"], "lines": [] }
