  "pages": [
    {
      "n": 1,
      "art": "A village house in spring: a whitewashed wall, a blossoming almond tree, a few red anemones in a pot by the door. A small wooden storeroom door stands open beside the house, dark inside. Grandma, rolling up her sleeves, stands in the doorway with a broom; Rose, seven, and her little cousin, four, wait beside her in old clothes, ready to help. Feeling: a cheerful job, sunshine and dust. Calm area: the blue sky above the roof, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 2,
      "art": "The yard filling up with old things: stacked baskets, cracked clay flowerpots, a rusty watering can, a chair with three legs. Rose carries a basket out of the storeroom; the little cousin sneezes in a little cloud of dust, holding his tummy and pulling a thirsty face. Feeling: hot, busy, a bit comic. Calm area: the sky across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 3,
      "art": "Inside the dim storeroom, behind a big cardboard box in the corner: a plain plastic bottle full of bright orange liquid stands on the floor next to a bucket and two scrubbing brushes. Its label is pale, faded and blank-looking (no words or symbols drawn). A stripe of sunlight from a gap in the wall makes the liquid glow like a lamp. The little cousin, squeezed behind the box, reaches towards the cap, eyes shining. Feeling: temptation, a held breath. Calm area: the dark upper wall across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 4,
      "art": "Close: Rose's hand has caught her cousin's small hand in mid-air, a hand's width from the bottle; the bottle stands untouched. Rose's face is calm and firm; the little cousin's lip wobbles. Feeling: a safe stop, gentle but sure. Calm area: the plain dark wall across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 5,
      "art": "Rose crouches at a safe distance from the bottle, hands on her knees, looking hard at it, thinking; around it, clearly not a kitchen: brushes, a bucket, a coil of old hose, a dusty shelf of tins. A small thought picture above her head shows a fridge far away with a jug of juice inside it. Feeling: careful thinking. Calm area: the upper wall across the top, beside the thought picture.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 6,
      "art": "Rose at the storeroom door, calling out into the sunny yard with one hand cupped by her mouth; with her other hand she holds her cousin's hand. He is pouting but standing still. Outside, a small bird sings on the almond tree. Feeling: patience, waiting for the right person. Calm area: the sky across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 7,
      "art": "Grandma bends over the bottle with her reading glasses on, reading the faded label closely without picking it up; then, in the same picture, she kneels and hugs both children tightly, eyes closed. Feeling: quiet relief and love; nothing frightening. Calm area: the upper wall across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 8,
      "art": "Grandma stands looking at a low wooden shelf in the storeroom with several bottles of different colours and shapes on it (no labels with words), one hand on her chin; Rose and her cousin stand beside her, the cousin with his chest puffed out proudly. Feeling: thinking ahead. Calm area: the upper wall across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 9,
      "art": "Grandma, standing on a sturdy low step, lifts a bottle up to the top shelf of a tall cupboard; several bottles already stand up there in a row. Rose stands back on the floor, counting on her fingers; the little cousin watches from beside Rose. The children do not touch the bottles. Feeling: careful, orderly. Calm area: the plain wall above the cupboard, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 10,
      "art": "The tall cupboard now closed; Grandma turns a small key in its lock and is about to hang the key on a hook high up beside the door, far out of a child's reach. The little cousin watches the key go up, head tilted back. Feeling: done properly. Calm area: the wall above the hook, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 11,
      "art": "At the kitchen table: Rose draws a big red hand with all five fingers spread on a sheet of paper, with a red crayon, concentrating. No words on the paper. Feeling: an idea, making something useful. Calm area: the plain kitchen wall across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 12,
      "art": "The closed storeroom cupboard with two red-hand drawings taped side by side on its door: Rose's big five-fingered hand, and her cousin's smaller hand with four fingers and a smiley face in the palm. The cousin is pressing the last piece of tape on; Grandma laughs behind them. Feeling: pride, a family joke. Calm area: the wall above the cupboard, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 13,
      "art": "The front step of the house in spring sunshine: Grandma, Rose and the little cousin sit in a row, each holding a cup of orange juice poured from a clear glass jug of freshly squeezed juice on the step beside them, with a few orange halves on a plate. The almond blossom behind them. Feeling: rest, warmth, together. Calm area: the sky above the roof, across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    },
    {
      "n": 14,
      "art": "Last picture of the book: close on the three of them on the step; the little cousin holds his cup in both hands and looks up at Grandma, very serious; Grandma is laughing; Rose grins. Through the open storeroom door in the background, the two red hands are just visible on the cupboard. Feeling: warm, funny, safe. Calm area: the sky across the top.",
      "zone": { "side": "full", "v": "top", "size": "m" },
      "image": null
    }
  ],
